import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTeachers() {
  const [teachers, setTeachers] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [formData, setFormData] = useState({ name: '', username: '', subject: 'Mathematics', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' });
  const [searchQuery, setSearchQuery] = useState('');

  const availableSubjects = ['Mathematics', 'Science', 'English', 'Sinhala', 'ICT', 'Accounting', 'Business Studies', 'Dancing', 'History'];

  const fetchTeachers = () => axios.get('http://localhost:8081/api/view-teachers').then(res => setTeachers(res.data));
  useEffect(() => { fetchTeachers(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const apiPath = isEditing ? `http://localhost:8081/api/edit-teacher/${editId}` : 'http://localhost:8081/api/add-teacher';
    const method = isEditing ? axios.put : axios.post;

    method(apiPath, formData).then((res) => { 
        if(res.data.status === "Error") {
            alert("Database Error: " + res.data.error); // Database එකේ අවුලක් නම් මේකෙන් පෙන්වයි
        } else {
            fetchTeachers(); resetForm(); alert("Success!"); 
        }
    }).catch(err => alert("Server connection error!"));
  };

  const handleEdit = (t) => {
    setIsEditing(true); setEditId(t.id);
    setFormData({ 
      name: t.name, username: t.username || '', 
      subject: t.Subject || t.subject || 'Mathematics', // කැපිටල්/සිම්පල් දෙකටම වැඩ
      qualifications: t.qualifications || '', email: t.email || '', 
      phone_number: t.phone_number, address: t.address || '', password: 'TC@123'
    });
    setShowForm(true);
  };

  const resetForm = () => { setShowForm(false); setIsEditing(false); setEditId(null); setFormData({ name: '', username: '', subject: 'Mathematics', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' }); };
  const filteredTeachers = [...teachers].sort((a, b) => b.id - a.id).filter(t => t.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div style={{ padding: '10px', fontFamily: 'sans-serif', animation: 'fadeIn 0.5s' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', backgroundColor: '#fff', padding: '15px 20px', borderRadius: '12px' }}>
        <h2 style={{ margin: 0, color: '#1e293b' }}>🧑‍🏫 Manage Teachers</h2>
        <button onClick={() => { resetForm(); setShowForm(true); }} style={{ padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>+ Add Teacher</button>
      </div>

      <div style={{ backgroundColor: '#fff', borderRadius: '12px', overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '1000px' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={thStyle}>Name</th><th style={thStyle}>Subject</th><th style={thStyle}>Qualifications</th><th style={thStyle}>Telephone</th><th style={thStyle}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredTeachers.map(t => (
              <tr key={t.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{...tdStyle, color: '#15803d', fontWeight: 'bold'}}>{t.name}</td>
                <td style={{...tdStyle, fontWeight: 'bold'}}>{t.Subject || t.subject || '-'}</td>
                <td style={{...tdStyle, maxWidth: '220px'}}>{t.qualifications || '-'}</td>
                <td style={{...tdStyle, whiteSpace: 'nowrap'}}>{t.phone_number}</td>
                <td style={tdStyle}>
                  <button onClick={() => handleEdit(t)} style={{ cursor: 'pointer', marginRight: '10px' }}>✏️</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '500px' }}>
            <h3>{isEditing ? 'Edit Teacher' : 'Add Teacher'}</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <input type="text" placeholder="Name" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required style={inputStyle} />
              <select value={formData.subject} onChange={e => setFormData({...formData, subject: e.target.value})} style={inputStyle} required>
                {availableSubjects.map(sub => <option key={sub} value={sub}>{sub}</option>)}
              </select>
              <input type="text" placeholder="Phone" value={formData.phone_number} onChange={e => setFormData({...formData, phone_number: e.target.value})} required style={inputStyle} />
              <div>
                <button type="button" onClick={resetForm} style={{ marginRight: '10px' }}>Cancel</button>
                <button type="submit">Save</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
const inputStyle = { padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', width: '100%' };
const thStyle = { padding: '12px', textAlign: 'left', color: '#475569' };
const tdStyle = { padding: '12px', borderBottom: '1px solid #f1f5f9' };
